mapper.select:
SELECT COUNT(1)
FROM sys_post_permission_grant
WHERE post_id = #{postId}
  AND permission_id = #{permissionId}

mapper.update:
UPDATE sys_post_permission_delegation
SET status = 'REVOKED',
    revoked_at = CURRENT_TIMESTAMP
WHERE source_post_id = #{sourcePostId}
  AND target_post_id = #{targetPostId}
  AND permission_id = #{permissionId}
  AND status = 'ACTIVE'

mapper.delete:
DELETE FROM sys_post_permission_grant
WHERE post_id = #{postId}
  AND permission_id = #{permissionId}
